struct jc_guide_topic *jc_guide_topics(void)
{
    return GUIDE_TOPICS;
}

const char *const *jc_guide_lines(const char *name)
{
    struct jc_guide_topic *t;

    if (name == NULL) {
        return NULL;
    }
    for (t = jc_guide_topics(); t->name != NULL; t++) {
        if (strcmp(t->name, name) == 0) {
            return t->lines;
        }
    }
    return NULL;
}

void jc_guide_append_topic(struct jc_sb *out, const char *name)
{
    const char *const *lines;

    if (name == NULL) {
        return;
    }
    lines = jc_guide_lines(name);
    if (lines == NULL) {
        return;
    }
    for (; *lines != NULL; lines++) {
        jc_sb_append(out, *lines);
    }
}

void jc_guide_skill_body(struct jc_sb *out)
{
    jc_sb_append(out, "# jichi guide\n");
    jc_sb_append(out, "\n");
    jc_sb_append(out, "## setup\n");
    jc_guide_append_topic(out, "setup");
    jc_sb_append(out, "## model\n");
    jc_guide_append_topic(out, "model");
    jc_sb_append(out, "## learner\n");
    jc_guide_append_topic(out, "learner");
    jc_sb_append(out, "## agents\n");
    jc_guide_append_topic(out, "agents");
    jc_sb_append(out, "## limits\n");
    jc_guide_append_topic(out, "limits");
    jc_sb_append(out, "## commands\n");
    jc_guide_append_topic(out, "commands");
    jc_sb_append(out, "Project-specific skills live in .jichi/skills/ and "
                    "are listed by `jichi skills`.\n");
}

void jc_skill_add_builtin(struct jc_skill_set *s, struct jc_arena *a)
{
    struct jc_skill sk;
    struct jc_sb body;
    char *b;
    int i;
    int found;

    if (s == NULL || a == NULL) {
        return;
    }
    jc_sb_init(&body);
    jc_guide_skill_body(&body);
    b = jc_sb_finish(&body);

    memset(&sk, 0, sizeof(sk));
    jc_vec_init(&sk.tools, sizeof(char *));
    sk.name = jc_arena_strdup(a, "jichi-guide");
    sk.description = jc_arena_strdup(a,
        "Set up or explain jichi. Load before configuring jichi, or "
        "before telling anyone how to use it.");
    sk.body = jc_arena_strdup(a, b != NULL ? b : "");
    free(b);
    sk.dir = jc_arena_strdup(a, "");

    /* Add-or-replace, mirroring jc_skill.c: a project skill named
     * jichi-guide loaded AFTER this wins on find; the built-in is
     * skipped when one already occupies the name. */
    found = 0;
    for (i = 0; i < jc_skill_count(s); i++) {
        if (strcmp(jc_skill_at(s, i)->name, "jichi-guide") == 0) {
            found = 1;
            break;
        }
    }
    if (!found) {
        jc_vec_push(&s->skills, &sk);
    }
}
